`timescale 1ns/1ps
// Multi-client real execution path: round-robin arbitration -> vector ALU ->
// tagged result FIFO, protected by a live-tag dependency scoreboard.
module tessera_vec_system #(parameter integer N_CLIENTS=4, OP_W=3, TAG_W=8, DATA_W=16, DEPTH=4, CLIENT_W=(N_CLIENTS<=2)?1:$clog2(N_CLIENTS), COUNT_W=$clog2(DEPTH+1), REC_W=CLIENT_W+TAG_W+2+DATA_W, DEP_TAGS=16)(input logic clk,rst_n,input logic [N_CLIENTS-1:0] req,input logic [N_CLIENTS*OP_W-1:0] op_bus,input logic [N_CLIENTS*TAG_W-1:0] tag_bus,input logic [N_CLIENTS*DATA_W-1:0] operand_a_bus,operand_b_bus,output logic [N_CLIENTS-1:0] grant,output logic completion_valid,input logic completion_ready,output logic [CLIENT_W-1:0] completion_client,output logic [TAG_W-1:0] completion_tag,output logic [1:0] completion_status,output logic [DATA_W-1:0] completion_result,output logic [COUNT_W-1:0] completion_occupancy);
logic tile_valid,tile_ready,tile_ready_raw,tile_done,tile_done_ready; logic [CLIENT_W-1:0] tile_client,done_client; logic [OP_W-1:0] tile_op; logic [TAG_W-1:0] tile_tag,done_tag; logic [DATA_W-1:0] tile_a,tile_b,done_result; logic [1:0] done_status; logic [N_CLIENTS-1:0] actual_grant; logic [REC_W-1:0] rec_in,rec_out; logic [COUNT_W-1:0] q_count; logic dep_alloc_ready,dep_complete_known,dep_duplicate,dep_unknown; logic [N_CLIENTS*DEP_TAGS-1:0] dep_live; logic [$clog2(N_CLIENTS*DEP_TAGS+1)-1:0] dep_count;
tessera_dispatcher #(.N_CLIENTS(N_CLIENTS),.CLIENT_W(CLIENT_W),.OP_W(OP_W),.TAG_W(TAG_W)) arb(.clk(clk),.rst_n(rst_n),.req(req),.op_bus(op_bus),.tag_bus(tag_bus),.grant(actual_grant),.cmd_valid(tile_valid),.cmd_ready(tile_ready),.cmd_client(tile_client),.cmd_op(tile_op),.cmd_tag(tile_tag));
assign grant=actual_grant;
// Tag allocation is tied to command acceptance; duplicate live tags backpressure dispatch.
assign tile_ready=tile_ready_raw&&dep_alloc_ready;
always @* begin tile_a=operand_a_bus[tile_client*DATA_W +: DATA_W]; tile_b=operand_b_bus[tile_client*DATA_W +: DATA_W]; end
tessera_vec_tile #(.CLIENT_W(CLIENT_W),.TAG_W(TAG_W),.DATA_W(DATA_W),.OP_W(OP_W)) tile(.clk(clk),.rst_n(rst_n),.cmd_valid(tile_valid),.cmd_ready(tile_ready_raw),.cmd_client(tile_client),.cmd_op(tile_op),.cmd_tag(tile_tag),.operand_a(tile_a),.operand_b(tile_b),.done_valid(tile_done),.done_ready(tile_done_ready),.done_client(done_client),.done_tag(done_tag),.done_status(done_status),.done_result(done_result),.busy());
tessera_dependency_scoreboard #(.N_CLIENTS(N_CLIENTS),.TAG_W(TAG_W),.CLIENT_W(CLIENT_W),.DEPTH(DEP_TAGS)) deps(.clk(clk),.rst_n(rst_n),.alloc_valid(tile_valid&&tile_ready),.alloc_ready(dep_alloc_ready),.alloc_client(tile_client),.alloc_tag(tile_tag),.complete_valid(completion_valid&&completion_ready),.complete_client(completion_client),.complete_tag(completion_tag),.complete_known(dep_complete_known),.duplicate_alloc(dep_duplicate),.unknown_completion(dep_unknown),.live_bitmap(dep_live),.live_count(dep_count));
assign rec_in={done_client,done_tag,done_status,done_result}; assign {completion_client,completion_tag,completion_status,completion_result}=rec_out; assign completion_occupancy=q_count;
tessera_command_fifo #(.WIDTH(REC_W),.DEPTH(DEPTH),.COUNT_W(COUNT_W)) result_fifo(.clk(clk),.rst_n(rst_n),.in_valid(tile_done),.in_ready(tile_done_ready),.in_data(rec_in),.out_valid(completion_valid),.out_ready(completion_ready),.out_data(rec_out),.occupancy(q_count));
endmodule
